#include "types.h"
#include "font.h"

/* one scenario trigger: type 0..3 are conditions, 4 is an action, 5 ends the list */
typedef struct StoryTrigger {
    u16 type;
    u16 opcode;
    s32 unk_4;
    s32 unk_8;
    s32 unk_C;
    s32 unk_10;
    f32 unk_14;
} StoryTrigger;

/* one chapter of the story mode (0x84 bytes, .rodata 0) */
typedef struct StoryChapter {
    u8 id;
    s8 course;
    u8 unk_2;
    u8 unk_3;
    char *title[5];
    char *movie[2];
    StoryTrigger *triggers[4];
    char *course_name;
    char *mission[5][3];
    char *story[5];
} StoryChapter;

/* the story progress in main_rel (lbl_1_bss_9C) */
typedef struct StoryProgress {
    s8 chapter;
    s8 difficulty;
    s8 port;
    s8 cleared;
    s16 unk_4;
    s8 unk_6;
    u8 unk_7;
    s32 mode;
} StoryProgress;

/* scenario state for the trigger functions (.bss 0x48) */
typedef struct StoryContext {
    u32 done[0x80];
    s32 timers[8];
    s32 counters[8];
    u32 flags240;
    u32 flags244;
    s16 unk_248;
    u32 unk_24C;
} StoryContext;

/* one entry of the mode table: name, then the init, main and exit functions */
typedef struct StoryModeEntry {
    char name[0x20];
    void (*init)(void);
    void (*main)(void);
    void (*exit)(void);
} StoryModeEntry;

typedef struct Vec {
    f32 x, y, z;
} Vec;

typedef struct ModelEntry {
    void *model;
    u32 unk_4;
} ModelEntry;

typedef struct ModelSet {
    u8 pad_0[8];
    ModelEntry *entries;
} ModelSet;

typedef struct Struct38460 {
    u8 pad_0[0x18];
    ModelSet *unk_18;
} Struct38460;

typedef struct GXColor {
    u8 r;
    u8 g;
    u8 b;
    u8 a;
} GXColor;

/* movie playback parameters in main_rel (lbl_1_bss_58) */
typedef struct MovieParams {
    s8 unk_0;
    u8 unk_1;
    u8 unk_2;
    u8 unk_3;
    u16 unk_4;
    u16 unk_6;
    u16 unk_8;
    u16 unk_A;
    f32 unk_C;
    f32 unk_10;
    u8 unk_14;
    u8 pad_15;
    u8 unk_16;
    s8 unk_17;
    s16 unk_18;
    u8 pad_1A[2];
    u32 unk_1C;
} MovieParams;

typedef struct PadStatus {
    u8 pad_0[8];
    u16 buttons;
    u8 pad_A[6];
    u16 unk_10;
    u16 unk_12;
} PadStatus;

typedef struct StoryTime {
    u8 min;
    u8 sec;
    u16 ms;
} StoryTime;

typedef struct SaveData {
    u8 pad_0[0x64];
    u16 unk_64;
    u8 pad_66[6];
    StoryTime times[8][12];
} SaveData;

typedef struct StoryClock {
    u8 pad_0[0x1e0];
    u8 min;
    u8 sec;
    u16 ms;
} StoryClock;

/* the course result screen in main_rel (lbl_1_bss_5138) */
typedef struct CourseResult {
    u16 unk_0;
    u8 count2;
    u8 count3;
    u8 list[4];
    u16 arr[4];
    u16 unk_10;
    u16 unk_12;
    u8 pad_14[0xCC];
    u8 unk_E0;
    u8 pad_E1;
    u8 unk_E2;
    u8 pad_E3[2];
    u8 unk_E5;
} CourseResult;

typedef struct GameTask {
    u32 flags;
    u8 pad_4[0xA4];
    s32 (*unk_A8)(u32 *);
    s32 (*unk_AC)(struct GameTask *);
    s32 (*unk_B0)(void);
    u32 unk_B4;
    s32 (*unk_B8)(void);
    s32 (*unk_BC)(struct GameTask *);
    s32 (*unk_C0)(void);
    s32 (*unk_C4)(void);
    s32 (*unk_C8)(struct GameTask *);
    s32 (*unk_CC)(void);
} GameTask;

typedef struct Struct970 {
    u32 unk_0;
    u8 unk_4;
} Struct970;

